var VIEWS = ["view_chrome", "view_link", "view_grid", "view_status", "view_bd", "view_sd", "view_rs", "view_cp", "view_hats", "view_rd", "view_mix"];
var GROUPS = {"voice": {"page": "kit", "members": [["view_bd", "bd_tune", "bd_sweep", "bd_decay", "bd_attack", "bd_soft", "bd_bits"], ["view_sd", "sd_tune", "sd_tone", "sd_snappy", "sd_bits"], ["view_rs", "rs_bits"], ["view_cp", "cp_bits"], ["view_hats", "hat_tune", "ch_decay", "oh_decay", "hat_bits"], ["view_rd", "rd_tune", "rd_bits"]]}};     // selector varname -> {page, members: [[varnames shown while it picks i]]}
var groupChoice = {};
(function () { for (var selector in GROUPS) groupChoice[selector] = 0; })();
var THEMES = {"dark": {"pad": [0.149, 0.149, 0.149, 1], "well": [0.106, 0.106, 0.11, 1], "ink": [0.835, 0.847, 0.859, 1], "inverse": [0.149, 0.149, 0.149, 1], "label": [0.557, 0.58, 0.608, 1], "unlit": [0.494, 0.518, 0.545, 1], "mint": [0.447, 0.871, 0.761, 1], "now": [0.176, 0.357, 1.0, 1], "rest": [0.2, 0.2, 0.21, 1], "beat": [0.26, 0.27, 0.28, 1]}, "light": {"pad": [0.835, 0.847, 0.859, 1], "well": [0.77, 0.78, 0.79, 1], "ink": [0.0, 0.0, 0.0, 1], "inverse": [1.0, 1.0, 1.0, 1], "label": [0.349, 0.369, 0.396, 1], "unlit": [0.451, 0.475, 0.502, 1], "mint": [0.12, 0.55, 0.45, 1], "now": [0.176, 0.357, 1.0, 1], "rest": [0.7, 0.71, 0.73, 1], "beat": [0.62, 0.63, 0.65, 1]}};
var liveColourMissingReported = false;
/** The 2sl tokens for Live's theme: light when Live's surface colour (live_surface_bg) is light. If Max can't
 *  give that colour, dark, and the Max window says which colour was missing (once, until it is back). */
function themeFromLive(who) {
  var surface = null, failure = "";
  try { surface = max.getcolor("live_surface_bg"); } catch (e) { failure = String(e); }
  var usable = surface && surface.length >= 3 && isFinite(surface[0]) && isFinite(surface[1]) && isFinite(surface[2]);
  if (!usable) {
    if (!liveColourMissingReported) {
      liveColourMissingReported = true;
      error("2sl drums (" + who + "): Live colour live_surface_bg is missing (max.getcolor gave " +
            (failure || JSON.stringify(surface)) + "): drawing in the dark theme\n");
    }
    return THEMES.dark;
  }
  liveColourMissingReported = false;
  var luminance = 0.2126 * surface[0] + 0.7152 * surface[1] + 0.0722 * surface[2];
  return luminance > 0.5 ? THEMES.light : THEMES.dark;
}
var currentPage = 0;
var ready = 0;

/** False when `name` belongs to a group its selector doesn't pick now. */
function shownByGroups(name) {
  for (var selector in GROUPS) {
    var members = GROUPS[selector].members;
    for (var j = 0; j < members.length; j++) {
      if (j !== groupChoice[selector] && members[j].indexOf(name) >= 0) return false;
    }
  }
  return true;
}

function show() {
  for (var i = 0; i < PAGE_NAMES.length; i++) {
    var list = PAGES[PAGE_NAMES[i]];
    for (var k = 0; k < list.length; k++) {
      outlet(0, "script", "sendbox", list[k], "hidden", i === currentPage && shownByGroups(list[k]) ? 0 : 1);
    }
  }
}

function group(selector, i) {
  if (!GROUPS[selector]) {
    error(DEVICE_NAME + ": group selector '" + selector + "' doesn't exist (a wiring error): ignored\n");
    return;
  }
  var last = GROUPS[selector].members.length - 1;
  if (!(i >= 0 && i <= last)) error(DEVICE_NAME + ": " + selector + " has no group " + i + " (0-" + last + "): showing the nearest\n");
  groupChoice[selector] = Math.max(0, Math.min(last, Math.round(i))) || 0;
  show();
}

function page(i) {
  var last = PAGE_NAMES.length - 1;
  if (!(i >= 0 && i <= last)) error(DEVICE_NAME + ": page " + i + " doesn't exist (0-" + last + "): showing the nearest\n");
  currentPage = Math.max(0, Math.min(last, Math.round(i))) || 0;
  show();
}

/** The patch object named `name` (its scripting name). The names come from the build, which checks them
 *  against the patch, so a missing one is a broken build: say which. */
function named(name, purpose) {
  var obj = this.patcher.getnamed(name);
  if (!obj) error(DEVICE_NAME + ": no object named '" + name + "' in the patch (" + purpose + ")\n");
  return obj;
}

function msg_int(i) {
  // Ignore the Preset menu while Live restores the set, so saved tweaks win.
  if (!ready) return;
  if (i < 0 || i >= PRESETS.length) {
    error(DEVICE_NAME + ": preset " + i + " doesn't exist (0-" + (PRESETS.length - 1) + "): nothing set\n");
    return;
  }
  var p = PRESETS[i];
  for (var name in p) {
    var obj = named(name, "preset " + i + " sets it");
    if (obj) obj.message(p[name]);
  }
}

function msg_float(v) {
  msg_int(Math.round(v));
}

// ---- 2sl colours on Live's controls ---------------------------------------------------------

function paint(name, attrs) {
  var obj = named(name, "recolouring");
  if (!obj) return;
  for (var a in attrs) obj.message([a].concat(attrs[a]));
}

function recolor() {
  var t = themeFromLive("controls");
  var clear = [0, 0, 0, 0];
  var i;
  // dials: an ink arc on an unlit track, labels in the label colour, focus in "now" blue
  for (i = 0; i < CONTROLS.dial.length; i++) paint(CONTROLS.dial[i], {
    activedialcolor: t.ink, dialcolor: t.rest, activeneedlecolor: t.ink, needlecolor: t.unlit,
    activefgdialcolor: t.ink, fgdialcolor: t.unlit, textcolor: t.label, panelcolor: clear, focusbordercolor: t.now
  });
  // toggles and buttons: 2sl chips, inverted when on
  for (i = 0; i < CONTROLS.text.length; i++) paint(CONTROLS.text[i], {
    activebgcolor: t.pad, activebgoncolor: t.ink, activetextcolor: t.ink, activetextoncolor: t.inverse,
    bgcolor: t.pad, bgoncolor: t.unlit, textcolor: t.label, textoffcolor: t.label, bordercolor: t.ink,
    focusbordercolor: t.now
  });
  for (i = 0; i < CONTROLS.menu.length; i++) paint(CONTROLS.menu[i], {
    activebgcolor: t.pad, textcolor: t.ink, tricolor: t.ink, bordercolor: t.ink, focusbordercolor: t.now,
    hltcolor: t.now, hlttextcolor: t.inverse
  });
  for (i = 0; i < CONTROLS.tab.length; i++) paint(CONTROLS.tab[i], {
    activebgcolor: t.pad, activebgoncolor: t.ink, textcolor: t.ink, textoncolor: t.inverse,
    bgcolor: t.pad, bgoncolor: t.unlit, inactivetextoffcolor: t.label, inactivetextoncolor: t.inverse,
    bordercolor: t.ink, focusbordercolor: t.now
  });
  for (i = 0; i < CONTROLS.numbox.length; i++) paint(CONTROLS.numbox[i], {
    activebgcolor: t.pad, textcolor: t.ink, bordercolor: t.ink, activeslidercolor: t.now, tricolor: t.ink,
    activetricolor: t.ink, focusbordercolor: t.now
  });
  for (i = 0; i < VIEWS.length; i++) {
    var v = named(VIEWS[i], "redrawing for the theme");
    if (v) v.message("theme");
  }
}

function anything() {
  if (messagename === "theme") {
    recolor();
    return;
  }
  if (messagename === "group") {
    var groupArguments = arrayfromargs(arguments);
    group(String(groupArguments[0]), groupArguments[1]);
    return;
  }
  if (messagename === "ready") {
    ready = 1;
    show();
    recolor();
    return;
  }
  error(DEVICE_NAME + ": the UI script doesn't know the message '" + messagename + "': ignored\n");
}
